<div class="bot-field"><label for="plugin-default-source">Domyślne źródło</label><select id="plugin-default-source" name="plugin[default_source]"><?php foreach($catalog['providers'] as $provider=>$label): ?><option value="<?= $provider ?>"<?= $editor['default_source']===$provider?' selected':'' ?>><?= $escape($label) ?></option><?php endforeach ?></select><small>Musi wskazywać skonfigurowany projekt. Pozostałe źródła będą opcjami komendy.</small></div></div>
